    metaEl.innerHTML = `<strong>Matter:</strong> ${sanitize(caseTitle)}<br/><strong>Due:</strong> ${due}`;
  }
  if (toggleBtn) {
    toggleBtn.textContent = task.done ? \"Mark Incomplete\" : \"Mark Complete\";
  }
  if (deleteBtn) {
